UPDATE providers.api_endpoints SET response_example='{"answer":"Apiosk is a payment infrastructure platform that enables AI agents and software to make payments and transact money. It allows developers to monetize their APIs, data services, and digital products by making them discoverable and payable through its network. Users can describe what they need, review pricing, and approve work before Apiosk handles the calls and returns results. The platform supports euro settlement through SEPA and provides bookkeeping-ready records. Apiosk also offers tools for developers to connect agents, publish services, and manage payments programmatically.","sources":[{"name":"Apiosk","url":"https://www.linkedin.com/company/apiosk"},{"name":"Apiosk | MCP Server","url":"https://mcp.so/servers/apiosk"}]}'::jsonb,response_body='{"type":"object","properties":{"answer":{"type":"string"},"sources":{"type":"array","items":{"type":"object","properties":{"url":{"type":"string"}},"required":["url"]}}},"required":["answer","sources"]}'::jsonb,external_docs_url='https://docs.linkup.so/pages/documentation/endpoints/search/reference' WHERE id='083326ff-e9f9-410f-bea4-0e2aaca9e56a';
